begin;
select set_config('qa.seller',gen_random_uuid()::text,true),set_config('qa.buyer',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at)
 select id,'authenticated','authenticated',id::text||'@example.invalid','{"role_name":"社区结算测试"}',now(),now() from(values(current_setting('qa.seller')::uuid),(current_setting('qa.buyer')::uuid))u(id);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role authenticated;
do $$ begin
 begin perform public.moxiu_community_read(current_setting('qa.seller')::uuid);raise exception 'Client called private community reader';exception when insufficient_privilege then null;end;
 begin perform public.moxiu_shared_context(current_setting('qa.seller')::uuid,'arena.challenge','[10000001]');raise exception 'Client read another character';exception when insufficient_privilege then null;end;
 begin perform * from moxiu_private.player_orders;raise exception 'Client directly changed escrow';exception when insufficient_privilege then null;end;
end;$$;
reset role;
do $$
declare a uuid:=current_setting('qa.seller')::uuid;b uuid:=current_setting('qa.buyer')::uuid; lot uuid:=gen_random_uuid(); buy uuid:=gen_random_uuid();match_id uuid:=gen_random_uuid();
 base jsonb:='{"player":{"stage":2},"playMs":1800000,"currency":{"stone":0,"cny":2000},"inventory":[],"world":{"mode":"standard"}}';
 item jsonb:='{"itemId":"jingmi","quality":"rare"}';projection jsonb:='{"stage":2,"power":200,"wealth":0,"speed":3}';
 sa jsonb;sb jsonb;r jsonb;c jsonb;ra bigint;rb bigint;season text:=to_char(now() at time zone 'Asia/Shanghai','YYYY-MM'); uid_a bigint;uid_b bigint;
begin
 perform public.moxiu_game_load(a,base);perform public.moxiu_game_load(b,base);
 r:=public.moxiu_game_commit_v2(a,1,null,'sync','[]',base,'{"ok":true}',projection);ra:=(r->>'revision')::bigint;
 r:=public.moxiu_game_commit_v2(b,1,null,'sync','[]',base,'{"ok":true}',projection);rb:=(r->>'revision')::bigint;
 r:=public.moxiu_shared_commit(a,ra,lot,'exchange.list','["seed",3,100,"cny"]',base,'{"ok":true,"qty":3}',projection,null,null,null,null,jsonb_build_object('entry',item,'slots',3));ra:=(r->>'revision')::bigint;
 assert r->'result'->>'order_id'=lot::text,'listing receipt and escrow';
 sb:=jsonb_set(jsonb_set(base,'{currency,cny}','1800'),'{inventory}','[{"uid":"received","itemId":"jingmi","quality":"rare","qty":2}]');
 sa:=jsonb_set(base,'{currency,cny}','2196');
 r:=public.moxiu_shared_commit(b,rb,buy,'exchange.buy',jsonb_build_array(lot,2),sb,'{"ok":true,"qty":2,"total":200,"fee":4}',projection,a,ra,sa,projection,'{"total":200,"fee":4}');
 assert r->'state'->'currency'->>'cny'='1800','buyer charged once';rb:=(r->>'revision')::bigint;
 c:=public.moxiu_game_load(a,base);ra:=(c->>'revision')::bigint;assert c->'state'->'currency'->>'cny'='2196','seller credited net tax atomically';
 r:=public.moxiu_shared_commit(b,rb-1,buy,'exchange.buy',jsonb_build_array(lot,2),sb,'{"ok":true}',projection,a,ra-1,sa,projection,'{}');
 assert r->>'replayed'='true' and (r->>'revision')::bigint=rb,'lost response replay does not repeat counterpart transfer';
 assert jsonb_array_length(public.moxiu_community_read(b)->'trades')=1,'one shared trade ledger record';
 r:=public.moxiu_shared_commit(b,rb,gen_random_uuid(),'exchange.buy',jsonb_build_array(lot,1),sb,'{"ok":true}',projection,a,ra-1,sa,projection,'{"total":100,"fee":2}');
 assert r->>'conflict'='true','stale seller snapshot cannot be overwritten by another buyer';
 r:=public.moxiu_game_commit_v2(a,ra,gen_random_uuid(),'reset','[]',base,'{"ok":true}',projection);ra:=(r->>'revision')::bigint;
 assert r->'result'->>'ok'='false' and r->'state'->'currency'->>'cny'='2196','active escrow blocks reset and preserves money';
 update moxiu_private.player_orders set expires_at=now()-interval '1 minute' where id=lot;
 c:=public.moxiu_community_read(a);assert jsonb_array_length(c->'offers')=0 and jsonb_array_length(c->'mine')=1,'expired listing hidden from buyers but reclaimable by owner';
 sa:=jsonb_set(sa,'{inventory}','[{"uid":"return","itemId":"jingmi","quality":"rare","qty":1}]');
 r:=public.moxiu_shared_commit(a,ra,gen_random_uuid(),'exchange.cancel',jsonb_build_array(lot),sa,'{"ok":true,"returned":1}',projection,null,null,null,null,'{}');ra:=(r->>'revision')::bigint;
 assert r->'state'->'inventory'->0->>'qty'='1' and jsonb_array_length(public.moxiu_community_read(a)->'mine')=0,'remaining escrow returned once';
 r:=public.moxiu_shared_commit(a,ra,gen_random_uuid(),'arena.enroll','[]',sa,'{"ok":true}',projection,null,null,null,null,'{}');ra:=(r->>'revision')::bigint;
 r:=public.moxiu_shared_commit(b,rb,gen_random_uuid(),'arena.enroll','[]',sb,'{"ok":true}',projection,null,null,null,null,'{}');rb:=(r->>'revision')::bigint;
 select uid into uid_a from public.moxiu_player_profiles where user_id=a;select uid into uid_b from public.moxiu_player_profiles where user_id=b;
 c:=public.moxiu_shared_context(b,'arena.challenge',jsonb_build_array(uid_a));assert c->>'enrolled'='true' and c->>'pair_used'='false','real opponent context';
 r:=public.moxiu_shared_commit(b,rb,match_id,'arena.challenge',jsonb_build_array(uid_a),sb,'{"ok":true}',projection,a,ra,sa,projection,jsonb_build_object('battle',jsonb_build_object('score',1,'rounds',4),'season',season,'rating',1012,'target_rating',988));rb:=(r->>'revision')::bigint;
 c:=public.moxiu_community_read(b);assert c->'self'->>'rating'='1012' and c->'self'->>'games'='1' and jsonb_array_length(c->'arena_board')=0,'real Elo applied but provisional player not ranked';
 assert c->>'challenges_today'='1' and jsonb_array_length(c->'matches')=1,'account daily quota and match audit';
 ra:=(public.moxiu_game_load(a,base)->>'revision')::bigint;
 c:=public.moxiu_shared_context(a,'arena.challenge',jsonb_build_array(uid_b));assert c->>'pair_used'='true','reverse challenge also counts as same daily pair';
 r:=public.moxiu_shared_commit(a,ra,gen_random_uuid(),'arena.challenge',jsonb_build_array(uid_b),sa,'{"ok":true}',projection,b,rb,sb,projection,jsonb_build_object('battle',jsonb_build_object('score',1,'rounds',4),'season',season,'rating',1000,'target_rating',1000));assert r->>'conflict'='true','pair race cannot produce a second match';
 r:=public.moxiu_shared_commit(b,rb-1,match_id,'arena.challenge',jsonb_build_array(uid_a),sb,'{"ok":true}',projection,a,ra-1,sa,projection,'{}');assert r->>'replayed'='true' and jsonb_array_length(public.moxiu_community_read(b)->'matches')=1,'match retry cannot score twice';
 r:=public.moxiu_game_commit_v2(a,ra,gen_random_uuid(),'reset','[]',base,'{"ok":true}',projection);
 assert r->'state'->'currency'->>'cny'='0' and r->>'market_linked'='true','post-trade reset cannot mint starter funds';
 assert public.moxiu_community_read(a)->'self'->>'rating'='988','reset cannot erase competitive rating';
 update moxiu_private.player_records set season='2000-01',rating=9999,games=99 where user_id=a;
 c:=public.moxiu_community_read(a);assert c->'self'->>'rating'='1000' and c->'self'->>'games'='0','new monthly season resets score without touching character';
end; $$;
rollback;
select 'community privileges, escrow, fees, retry, CAS, expiration, reset, Elo, pair quota and season: passed' as result;
